shader_body
{
uv = 0.5 + (uv-0.5)*vec2( 1.0 ,-1);
vec3 base = GetBlur3(uv) + GetBlur2(uv).xy + GetBlur1(uv) + texture(sampler_main, uv) + 0.0;
a =base.x / 4.0;b = base.y / 4.0; c = base.z / 4.0;
c = c + b - c*b;
a = a + c - a*c;
base = 1.4*a;
ret = clamp01(base*(0.8-base) * 6.0*vec3(0.2,-0.1, 1.0 )) + 0.5*pow(base,0.5)*vec3(1.3,0.6,-0.5);
//ret.xy = ret.yx;
}

